class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k = k % n;

        reverse(nums, 0, n - 1);
        reverse(nums, 0, k - 1);
        reverse(nums, k, n - 1);
    }

    private void reverse(int[] nums, int left, int right) {
        while(left < right){
            int temp = nums[left];
            nums[left] = nums[right];
            nums[right] = temp;
            left++;
            right--;
        }
    }
}

class Solution {
    public void rotate(int[] nums, int k) {
        int n = nums.length;
        k = k % n;

        int temp[] = new int[k];

        // copy rotated part
        for(int i = (n - k); i < n; i++){
            temp[i - (n - k)] = nums[i];
        }

        // shift non-rotated part
        for(int i = (n - k - 1); i >= 0; i--){
            nums[i + k] = nums[i];
        }

        // put rotated part in array
        for(int i = 0; i < k; i++){
            nums[i] = temp[i];
        }
    }
}
